const uno = part('uno', 'arduino-uno', [-30, -10]);
const r = part('r', 'resistor', [4, -4], 0, { value: '220' });
const led = part('led', 'led', [14, -4], 0, { color: 'red' });
wire('drive', uno.pin('9'), r.pin('1'), 'green', [[x(uno.pin('9')), -130], [x(r.pin('1')), -130]]);
wire('led-feed', r.pin('2'), led.pin('A'), 'green', [[x(r.pin('2')), -80], [x(led.pin('A')), -80]]);
wire('ground', uno.pin('GND.2'), led.pin('C'), 'black', [[x(uno.pin('GND.2')), 130], [x(led.pin('C')), 130]]);
